using UnityEngine;

namespace HimoHito
{
    // One read-only intent/pendulum state for torso, hips, knees and knitted arms.
    // No clock-driven cycle; no writes to root, input, velocity, joint or resource.
    public sealed class BodyPumpPresentation
    {
        public Vector3 BodyDegrees { get; private set; }
        public Vector4 ArmDegrees { get; private set; } = new Vector4(-15,-50,20,55);
        public float Weight { get; private set; }
        public float Intent { get; private set; }
        public float Bottom { get; private set; }
        public float Apex { get; private set; }
        public float SignedSpeed { get; private set; }
        public string Phase { get; private set; } = "idle";
        float travel=1,releaseWeight;
        bool wasAttached;

        public void Advance(bool attached,bool grounded,bool ready,float settle,
            Vector2 radial,Vector2 velocity,float input,float dt,bool relocated)
        {
            if(dt<=0)return;
            if(relocated){Weight=0;BodyDegrees=Vector3.zero;Intent=0;wasAttached=false;}
            if(!attached)
            {
                if(wasAttached)releaseWeight=Weight;
                Weight=grounded?0:releaseWeight*settle;
                if(Weight<=.001f){BodyDegrees=Vector3.zero;Intent=0;}
                Phase=Weight>0?"release_handoff":"idle";
                wasAttached=false;return;
            }
            if(!wasAttached){Weight=0;BodyDegrees=Vector3.zero;Intent=0;}
            wasAttached=true;
            SignedSpeed=Vector2.Dot(velocity,new Vector2(-radial.y,radial.x));
            if(Mathf.Abs(SignedSpeed)>.45f)travel=Mathf.Sign(SignedSpeed);
            float speed=Mathf.Abs(SignedSpeed);
            Bottom=Mathf.SmoothStep(0,1,Mathf.InverseLerp(.70f,.98f,-radial.y));
            Apex=(1-Mathf.SmoothStep(0,1,Mathf.InverseLerp(.5f,3.6f,speed))) *
                Mathf.SmoothStep(0,1,Mathf.InverseLerp(.08f,.22f,Mathf.Abs(radial.x)));
            Intent=Mathf.Lerp(Intent,input,1-Mathf.Exp(-dt/.075f));
            bool pressing=Mathf.Abs(input)>.05f;
            bool brake=pressing&&input*SignedSpeed<-.4f;
            float rise=Mathf.SmoothStep(0,1,Mathf.InverseLerp(0,3,velocity.y));
            float fast=Mathf.SmoothStep(0,1,Mathf.InverseLerp(3,10,speed));
            Vector3 passive=new Vector3(-travel*(5+8*Bottom*fast),travel*(5+15*Apex),-travel*(10+30*Apex));
            // Downstroke: hip and feet extend with the intended tangent.
            // Ascent: fold at the hip; apex: gather the knees for the next stroke.
            // Do not cancel all three joints into the same dangling silhouette.
            Vector3 effort=new Vector3(Intent*(20-4*rise+4*Bottom),
                Intent*(28*Bottom-30*rise+30*Apex),Intent*(16*Bottom-28*rise-55*Apex));
            Vector3 target=Vector3.Lerp(passive,effort,Mathf.Abs(Intent));
            Vector4 arms=travel>0?new Vector4(-22,-32,-8,-18):new Vector4(8,18,22,32);
            if(pressing)
            {
                // Shoulder opposition accompanies the same trunk effort, not a second dance.
                Vector4 drive=Intent>=0?new Vector4(-38,-76,66,112):new Vector4(-66,-112,38,76);
                Vector4 fold=Intent>=0?new Vector4(-36,-100,52,126):new Vector4(-52,-126,36,100);
                arms=Vector4.Lerp(arms,Vector4.Lerp(drive,fold,Mathf.Max(rise*.55f,Apex)),Mathf.Abs(Intent));
            }
            else arms=Vector4.Lerp(arms,new Vector4(-30,-66,30,66),Apex);
            if(brake)
            {
                target=new Vector3(input*23,-travel*19,travel*38);
                arms=travel>0?new Vector4(-46,-110,26,90):new Vector4(-26,-90,46,110);
            }
            if(grounded||!ready)
            {
                target=Vector3.zero;arms=new Vector4(-15,-50,20,55);
                Weight=0;Phase=grounded?"ground_brace":"original_attach";
            }
            else
            {
                Weight=Mathf.MoveTowards(Weight,1,dt/.16f);
                Phase=brake?"brake_gather":Apex>.55f?(pressing?"active_apex_prepare":"coast_apex"):
                    Bottom>.85f&&speed>6?(pressing?"active_bottom_drive":"coast_bottom_lag"):
                    pressing?(velocity.y>.3f?"active_ascent_fold":"active_downstroke"):"coast";
            }
            BodyDegrees=Vector3.Lerp(BodyDegrees,target,1-Mathf.Exp(-dt/.075f));
            // Sleeve follows the torso decision slightly later, as a soft limb, no stretch.
            ArmDegrees=Vector4.Lerp(ArmDegrees,arms,1-Mathf.Exp(-dt/.115f));
        }
    }
}
